def validate(data: dict, schema: dict[str, type]) -> list[str]:
    errors = []

    # Check for missing fields
    for field in schema:
        if field not in data:
            errors.append(f"missing: {field}")

    # Check for type mismatches
    for field, expected_type in schema.items():
        if field in data:
            value = data[field]
            # Special handling: bool should not count as int
            if expected_type is int and isinstance(value, bool):
                errors.append(f"type: {field}")
            elif expected_type is float and isinstance(value, int) and not isinstance(value, bool):
                errors.append(f"type: {field}")
            elif not isinstance(value, expected_type):
                errors.append(f"type: {field}")

    # Check for extra fields
    for field in data:
        if field not in schema:
            errors.append(f"extra: {field}")

    return sorted(errors)
